Given an array arr[] of integers, find the smallest and second smallest distinct elements in the array. The result should be returned in ascending order, meaning the smallest element should come first, followed by the second smallest. If there is no valid second smallest (i.e., all elements are the same or the array has fewer than two elements), then return -1.  Examples:Input: arr[] = [12, 25, 8, 55, 10, 33, 17, 11]Output: [8, 10]Explanation: The smallest element is 1 and second smallest element is 10.Input: arr[] = [2, 4, 3, 5, 6]Output: [2, 3]Explanation: 2 and 3 are respectively the smallest and second smallest elements in the array.Input: arr[] = [1, 1, 1]Output: [-1]Explanation: Only element is 1 which is smallest, so there is no second smallest element.Try It YourselfTable of Content[Naive Approach] Using Sorting - O(n × log(n)) Time and O(1) Space[Better Approach] Using Two Pass - O(n) Time and O(1) Space[Expected Approach] Using Single Pass - O(n) Time and O(1) Space[Naive Approach] Using Sorting - O(n × log(n)) Time and O(1) SpaceThe Idea is to is first sorted the array in ascending order, which ensures that the smallest element is at the front. Then, the code searches for the first number that is greater than the minimum to identify the second smallest. If all elements are equal and no distinct second minimum exists, it returns -1. 
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

vector<int> minAnd2ndMin(vector<int> &arr) {

    // sort the array in ascending order
    sort(arr.begin(), arr.end());

    int n = arr.size();

    // initialize minimum and second minimum with 
    // smallest possible integer
    int mini = INT_MIN, secmini = INT_MIN;

    // the first element after sorting is the minimum
    mini = arr[0];

    // find the first element greater than mini 
    // (i.e., second minimum)
    for(int i = 0; i < n; i++) {

        if(arr[i] != mini) {
            secmini = arr[i];
            break;
        }
    }

    // if no second minimum found (i.e., all elements are equal)
    // return -1
    if(secmini == INT_MIN) {
        return {-1};
    }

    // return both minimum and second minimum
    return {mini, secmini};
}

int main() {
    vector<int> arr = {12, 25, 8, 55, 10, 33, 17, 11};
    vector<int> res = minAnd2ndMin(arr);
    for(auto it : res) {
        cout << it << " ";
    }
    cout << "\n";
    return 0;
}


