[Better Approach] Using Two Pass - O(n) Time and O(1) SpaceThe main idea of this approach is to find the smallest and second smallest distinct elements in the array using two separate passes. In the first loop, it identifies the minimum value (mini) by comparing each element. In the second loop, it looks for the smallest element that is not equal to the minimum, which becomes the second minimum (secmini). This ensures that both values are distinct. 
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

vector<int> minAnd2ndMin(vector<int> &arr) {

    int n = arr.size();
    int mini = INT_MAX;      
    int secmini = INT_MAX;

    // First loop to find the minimum element in the array
    for(int i = 0; i < n; i++) {
        mini = min(mini, arr[i]);
    }

    // Second loop to find the second minimum element 
    for(int i = 0; i < n; i++) {
        if(arr[i] != mini) {
            secmini = min(secmini, arr[i]);
        }
    }

    // If second minimum was not updated, it means all elements are equal
    if(secmini == INT_MAX) {
        return {-1};  
    }

    return {mini, secmini};
}

int main() {
    vector<int> arr = {12, 25, 8, 55, 10, 33, 17, 11}; 
    vector<int> res = minAnd2ndMin(arr);  

    for(auto it : res) {
        cout << it << " ";
    }
    cout << "\n";

    return 0;
}


