[Expected Approach] Using Single Pass - O(n) Time and O(1) SpaceThe main idea of this approach is to find the smallest and second smallest distinct elements by scanning the array only once. It uses two variables: first for the minimum value and second for the second minimum. The values are updated based on the following conditions:=> If the current number is less than first: Update second = first and first = current number.=> Else if the current number is greater than first but less than second: Update second = current number.
            C++

    #include <iostream>
#include <vector>
#include <climits>
using namespace std;

vector<int> minAnd2ndMin(const vector<int> &arr) {

    int n = arr.size();

    // Need at least two elements to have a second minimum
    if (n < 2) {
        return { -1 };
    }

    // Initialize first and second minimums to "infinity"
    int first = INT_MAX;
    int second = INT_MAX;

    // Single pass over the array
    for (int i = 0; i < n; i++) {

        // Found new minimum: shift down the old minimum
        if (arr[i] < first) {
            second = first;
            first = arr[i];
        }

        // arr[i] is not equal to first but smaller than current second
        else if (arr[i] < second && arr[i] != first) {
            second = arr[i];
        }
    }

    // If second was never updated, all elements were equal
    if (second == INT_MAX) {
        return { -1 };
    }

    // Return the two minima
    return { first, second };
}

int main() {
    vector<int> arr = {12, 25, 8, 55, 10, 33, 17, 11};
    vector<int> res = minAnd2ndMin(arr);

    for (int x : res) {
        cout << x << " ";
    }
    cout << "\n";

    return 0;
}


